    """反复删除列表中相邻的重复对。"""
    while True:
        new_tokens = []
        has_removed = False
        for i in range(len(tokens)):
            if i > 0 and tokens[i] == tokens[i - 1]:
                has_removed = True
                continue
            new_tokens.append(tokens[i])
        if not has_removed:
            break
        tokens = new_tokens
    return tokens
