def three_sum_closest(nums, target):
    """返回和为target的三个下标。"""
    triples = sorted((v, i) for i, v in enumerate(nums))
    n = len(triples)
    closest_sum = float('inf')
    result_indices = []
    for a in range(n - 2):
        lo, hi = a + 1, n - 1
        while lo < hi:
            s = triples[a][0] + triples[lo][0] + triples[hi][0]
            if abs(s - target) < abs(closest_sum - target):
                closest_sum = s
                result_indices = [triples[a][1], triples[lo][1], triples[hi][1]]
            if s == target:
                return sorted(result_indices)
            if s < target:
                lo += 1
            else:
                hi -= 1
    return result_indices
```

