def search_range(nums, target):
    """返回target的首尾位置。"""
    def find_first(nums, target):
        lo, hi = 0, len(nums) - 1
        first = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] >= target:
                hi = mid - 1
            else:
                lo = mid + 1
        if lo < len(nums) and nums[lo] == target:
            first = lo
        return first

    def find_last(nums, target):
        lo, hi = 0, len(nums) - 1
        last = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] <= target:
                lo = mid + 1
            else:
                hi = mid - 1
        if hi >= 0 and nums[hi] == target:
            last = hi
        return last

    first = find_first(nums, target)
    last = find_last(nums, target)
    return [first, last]
```

