def max_subarray(nums):
    """返回最大子数组的和与起止下标。"""
    best = None
    for i in range(len(nums)):
        for j in range(i, len(nums)):
            s = sum(nums[i:j + 1])
            if best is None or s > best[0] or (s == best[0] and (j - i < best[2] - best[1] or (j - i == best[2] - best[1] and i < best[1]))):
                best = (s, i, j)
    return [best[0], best[1], best[2]]
```

