def longest_mountain(nums):
    """返回最长山峰子数组的长度。"""
    best = 0
    for i in range(1, len(nums) - 1):
        if nums[i - 1] < nums[i] > nums[i + 1]:
            left = i
            while left > 0 and nums[left - 1] < nums[left]:
                left -= 1
            right = i
            while right < len(nums) - 1 and nums[right] > nums[right + 1]:
                right += 1
            best = max(best, right - left + 1)
    return best
```
